import{c as a,Q as s,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const n="/assets/zh-cn_formulaimage_0000002391544929.kRpnJPs5.png",m=JSON.parse('{"title":"AddReluCast","description":"","frontmatter":{},"headers":[{"level":1,"title":"AddReluCast","slug":"addrelucast"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/复合计算/AddReluCast.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/复合计算/AddReluCast.md"}'),d={name:"api/SIMD-API/基础API/Memory矢量计算/复合计算/AddReluCast.md"};function i(r,t,p,o,c,h){return s(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="addrelucast" tabindex="-1">AddReluCast <a class="header-anchor" href="#addrelucast" aria-label="Permalink to &quot;AddReluCast&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按元素求和，结果和0对比取较大值，并根据源操作数和目的操作数Tensor的数据类型进行精度转换。计算公式如下，其中dstType表示目的操作数的数据类型：</p><p><img src="'+n+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>tensor前n个数据计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void AddReluCast(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src0, const LocalTensor&lt;U&gt;&amp; src1, const uint32_t count)</span></span></code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void AddReluCast(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src0, const LocalTensor&lt;U&gt;&amp; src1, uint64_t mask[], const uint8_t repeatTime, const BinaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void AddReluCast(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;U&gt;&amp; src0, const LocalTensor&lt;U&gt;&amp; src1, uint64_t mask, const uint8_t repeatTime, const BinaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>目的操作数数据类型。不同数据类型对应的精度转换规则见表3。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t、half、int32_t、float。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int8_t、half。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int8_t、half。 Atlas 200I/500 A2 推理产品， 支持的数据类型为int8_t、half。 Atlas 推理系列产品AI Core，支持的数据类型为：int8_t、half。</td></tr><tr><td>U</td><td>源操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int16_t、half、float、int64_t。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int16_t、half、float。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int16_t、half、float。 Atlas 200I/500 A2 推理产品， 支持的数据类型为half、float。 Atlas 推理系列产品AI Core，支持的数据类型为：int16_t、half、float。</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask。 true，表示在接口内部设置mask。false，表示在接口外部设置mask，开发者需要使用SetVectorMask接口设置mask值。这种模式下，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src0、src1</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr><tr><td>mask[]/mask</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。 当源操作数和目的操作数位数不同时，以数据类型的字节较大的为准。例如，源操作数为half类型，目的操作数为int8_t类型，计算mask时以half为准。</td></tr><tr><td>repeatTime</td><td>输入</td><td>重复迭代次数。矢量计算单元，每次读取连续的256Bytes数据进行计算，为完成对输入数据的处理，必须通过多次迭代（repeat）才能完成所有数据的读取与计算。 关于该参数的具体描述请参考高维切分API。</td></tr><tr><td>repeatParams</td><td>输入</td><td>控制操作数地址步长的参数。BinaryRepeatParams类型，包含操作数相邻迭代间相同datablock的地址步长，操作数同一迭代内不同datablock的地址步长等参数。 相邻迭代间的地址步长参数说明请参考repeatStride；同一迭代内DataBlock的地址步长参数说明请参考dataBlockStride。</td></tr></tbody></table><p><strong>表 3</strong> 精度转换规则</p><table tabindex="0"><thead><tr><th>源操作数的数据类型</th><th>目的操作数的数据类型</th><th>类型转换模式介绍</th></tr></thead><tbody><tr><td>float</td><td>half</td><td>将源操作数按照CAST_NONE模式取到half所能表示的数，以half格式（溢出默认按照饱和处理）存入目的操作数中。</td></tr><tr><td>half</td><td>int8_t</td><td>将源操作数按照CAST_NONE模式取整，以int8_t格式（溢出默认按照饱和处理）存入目的操作数中。</td></tr><tr><td>int16_t</td><td>int8_t</td><td>将源操作数按照CAST_NONE模式取到int8_t所能表示的数，以int8_t格式（溢出默认按照饱和处理）存入目的操作数中。</td></tr><tr><td>int64_t</td><td>float</td><td>将源操作数按照CAST_NONE模式取整，以float格式（溢出默认按照饱和处理）存入目的操作数中。</td></tr><tr><td>int64_t</td><td>int32_t</td><td>将源操作数按照CAST_NONE模式取到int32_t所能表示的数，以int32_t格式（溢出默认按照饱和处理）存入目的操作数中。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>针对Ascend 950PR/Ascend 950DT，int64_t数据类型仅支持tensor前n个数据计算接口。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本样例的srcLocal为half类型，dstLocal为int8_t类型，计算mask时以half为准。</p><ul><li><p>tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask = 256 / sizeof(half); // 128</span></span>
<span class="line"><span>// repeatTime = 4，一次迭代计算128个数，共计算512个数</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1，单次迭代内数据连续读取和写入</span></span>
<span class="line"><span>// dstRepStride = 4，src0RepStride, src1RepStride = 8，相邻迭代间数据连续读取和写入</span></span>
<span class="line"><span>AscendC::AddReluCast(dstLocal, src0Local, src1Local, mask, 4, { 1, 1, 1, 4, 8, 8 });</span></span></code></pre></div></li><li><p>tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask[2] = { UINT64_MAX, UINT64_MAX };</span></span>
<span class="line"><span>// repeatTime = 4，一次迭代计算128个数，共计算512个数</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1，单次迭代内数据连续读取和写入</span></span>
<span class="line"><span>// dstRepStride = 4，src0RepStride, src1RepStride = 8，相邻迭代间数据连续读取和写入</span></span>
<span class="line"><span>AscendC::AddReluCast(dstLocal, src0Local, src1Local, mask, 4, { 1, 1, 1, 4, 8, 8 });</span></span></code></pre></div></li><li><p>tensor前n个数据计算样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::AddReluCast(dstLocal, src0Local, src1Local, 512);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据src0Local: [1 1 3 ... 512]</span></span>
<span class="line"><span>输入数据src1Local：[0 0.5 -4 ... -513]</span></span>
<span class="line"><span>输出数据dstLocal：[1 2 0 ... 0]</span></span></code></pre></div>`,24)])])}const A=a(d,[["render",i]]);export{m as __pageData,A as default};
